(async () => {
  const orig = window.fetch.bind(window);
  window.fetch = async (input, init) => {
    const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
    if (/\/api\/browser-engine\/install/.test(url)) return new Response(JSON.stringify({ error: "The download server didn't answer." }), { status: 503, headers: { 'content-type': 'application/json' } });
    return orig(input, init);
  };
  const urls = performance.getEntriesByType('resource').map((e) => e.name);
  const pick = (re) => urls.find((u) => re.test(new URL(u).pathname));
  const [client, react, line] = await Promise.all([import(pick(/\/deps\/react-dom_client\.js$/)), import(pick(/\/deps\/react\.js$/)), import('/src/components/BrowserPartLine.tsx')]);
  const createRoot = client.createRoot ?? client.default.createRoot;
  const h = react.createElement ?? react.default.createElement;
  const log = document.querySelector('[role=log]');
  const rows = log.querySelector('[data-mid]')?.parentElement ?? log;
  const host = document.createElement('div');
  host.className = 'flex justify-start px-0 py-3';
  host.dataset.stagedBrowserPart = '';
  rows.append(host);
  createRoot(host).render(h(line.BrowserPartLine, { part: { phase: 'failed', received: 0, total: 1, botIds: [] } }));
  return true;
})()
